  second: ConflictEntry;
}

interface WeeklyHoursRow {
  staffId: string;
  staffName: string;
  scheduledMinutes: MinutesFromMidnight;
  weeklyHourCapMinutes: MinutesFromMidnight;
  remainingMinutes: MinutesFromMidnight;
}

/**
 * Pure interval overlap: two intervals overlap iff startA < endB && startB < endA.
 * Touching intervals (startA === endB) are NOT overlapping.
 * @param startA start of first interval in minutes-from-midnight
 * @param endA end of first interval in minutes-from-midnight
 * @param startB start of second interval in minutes-from-midnight
 * @param endB end of second interval in minutes-from-midnight
 * @returns true when the intervals overlap
 */
// req-11, req-12
function overlaps(
  startA: MinutesFromMidnight,
  endA: MinutesFromMidnight,
  startB: MinutesFromMidnight,
  endB: MinutesFromMidnight
): boolean {
  return startA < endB && startB < endA;
}

/**
 * Return the Monday-to-Sunday date strings for the week containing the given date.
 * @param date the anchor date in YYYY-MM-DD form
 * @returns seven date strings Monday through Sunday
 */
// req-2
function weekDates(date: DateString): DateString[] {
  const parts: string[] = date.split('-');
  const year: number = Number(parts[0]);
  const month: number = Number(parts[1]);
  const day: number = Number(parts[2]);
  const base: number = Date.UTC(year, month - 1, day);
  const dow: number = new Date(base).getUTCDay();
  const offset: number = (dow + 6) % 7;
  const monday: number = base - offset * 86400000;
  const out: DateString[] = [];
  for (let i = 0; i < 7; i = i + 1) {
    const d: Date = new Date(monday + i * 86400000);
    const y: number = d.getUTCFullYear();
    const m: number = d.getUTCMonth() + 1;
    const dd: number = d.getUTCDate();
    const mm: string = m < 10 ? '0' + String(m) : String(m);
    const ddd: string = dd < 10 ? '0' + String(dd) : String(dd);
    out.push(String(y) + '-' + mm + '-' + ddd);
  }
  return out;
}

/**
 * Sum the durations of all shifts for a staff member inside a set of dates.
 * @param shifts the full shift list to scan
 * @param staffId the staff id to total
 * @param dates the date strings in scope
 * @returns total scheduled minutes
 */
// req-2, req-4
function sumShiftMinutes(shifts: Shift[], staffId: string, dates: DateString[]): MinutesFromMidnight {
  let total: number = 0;
  for (let i = 0; i < shifts.length; i = i + 1) {
    const s: Shift = shifts[i];
    if (s.staff === staffId && dates.indexOf(s.date) !== -1) {
      total = total + (s.end - s.start);
    }
  }
  return total;
}

/**
 * Build the running weekly-hours rows for every staff member in scope.
 * @param data the schedule data
 * @param weekMonday the Monday date string of the target week
 * @returns one row per staff member with scheduled, cap and remaining minutes
 */
// req-4, req-2
function getStaffWeeklyHours(data: ScheduleData, weekMonday: DateString): WeeklyHoursRow[] {
  const dates: DateString[] = weekDates(weekMonday);
  const rows: WeeklyHoursRow[] = [];
  for (let i = 0; i < data.staff.length; i = i + 1) {
    const st: Staff = data.staff[i];
    const scheduled: MinutesFromMidnight = sumShiftMinutes(data.shifts, st.id, dates);
    rows.push({
      staffId: st.id,
      staffName: st.name,
      scheduledMinutes: scheduled,
      weeklyHourCapMinutes: st.weeklyHourCapMinutes,
      remainingMinutes: st.weeklyHourCapMinutes - scheduled
    });
  }
  return rows;
}
export { overlaps, weekDates, getStaffWeeklyHours };

